def solve(I):
    H,W=len(I),len(I[0]); bg=I[0][0]
    anoms=sorted((r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=bg)
    ans=[row[:] for row in I]
    rs={r for r,_,_ in anoms}; cs={c for _,c,_ in anoms}
    horiz = len(rs)==1 and len(cs)>1
    vert   = len(cs)==1 and len(rs)>1
    if horiz:
        parities=[]
        for r0,c0,v in anoms: parities.append(((r0+c0)%2,c0,v))
        # strip columns assigned to anchors; overlapping resolution by later anchor? just assign block to anchor index
        used=set()
        assignments={}
        for k,(p,c0,v) in enumerate(parities):
            blk=tuple(sorted(set(range(c0-1,c0+2))))
            for c in blk:
                if c not in used: assignments[c]=k
        for c,k in assignments.items():
            p,_,v=parities[k]
            for r in range(H):
                if (r+c)%2==p: ans[r][c]=v
    elif vert:
        parities=[]
        for r0,c0,v in anoms: parities.append(((r0+c0)%2,r0,v))
        used=set(); assignments={}
        for k,(p,r0,v) in enumerate(parities):
            blk=tuple(sorted(set(range(r0-1,r0+2))))
            for r in blk:
                if r not in used: assignments[r]=k
        for r,k in assignments.items():
            p,_,v=parities[k]
            for c in range(W):
                if (r+c)%2==p: ans[r][c]=v
    else:
        for r in range(max(0,min(r for r,_,_ in anoms)-1),min(H,max(r for r,_,_ in anoms)+2)):
            for c in range(W):
                pass
        # single anomaly: expand both ways like demos show -> rows ar-1..ar+1 full width
        r0,c0,v=anoms[0]
        for r in range(max(0,r0-1),min(H,r0+2)):
            for c in range(W):
                if (r+c)%2==(r0+c0)%2: ans[r][c]=v
    return ans
